import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function region(text, kind) {
    return <div className={'region ' + kind}>
    {text}
    </div>;
}
function App() {
    var mode = React.useState('left'), gap = React.useState(true), footer = React.useState(false);
    var choices = [['main', 'Основной'], ['left', 'Слева'], ['right', 'Справа'], ['both', 'С двух сторон']];
    return <div className="dspagelayout-example">
    <style>{exampleStyles}</style>
    <div className={"demo-stack"}>
    <div className={'row'} role={'group'} aria-label={'Расположение боковых регионов'}>
    {choices.map(function (item) {
            return <S.DsButton key={item[0]} tone={mode[0] === item[0] ? 'primary' : 'secondary'} aria-pressed={mode[0] === item[0]} onClick={function () { mode[1](item[0]); }}>
    {item[1]}
    </S.DsButton>;
        })}
    </div>
    <div className={'row'}>
    <S.DsButton tone={!gap[0] ? 'primary' : 'secondary'} aria-pressed={!gap[0]} onClick={function () { gap[1](!gap[0]); }}>
    {'Без отступов'}
    </S.DsButton>
    <S.DsButton tone={footer[0] ? 'primary' : 'secondary'} aria-pressed={footer[0]} onClick={function () { footer[1](!footer[0]); }}>
    {'Нижний регион'}
    </S.DsButton>
    </div>
    <div className={'stage'}>
    <S.DsPageLayout responsive={true} mainId={'layout-regions'} skipLinkLabel={'К схеме регионов'} leftLabel={'Список'} rightLabel={'Сведения'} header={region('Шапка приложения', 'header')} pageHeader={region('Заголовок страницы', 'heading')} left={mode[0] === 'left' || mode[0] === 'both' ? region('Левый регион', 'side') : undefined} right={mode[0] === 'right' || mode[0] === 'both' ? region('Правый регион', 'side') : undefined} leftWidth={'clamp(80px, 20vw, 180px)'} rightWidth={'clamp(80px, 20vw, 180px)'} gap={gap[0]} footer={footer[0] ? region('Нижний регион', 'footer') : undefined}>
    {region('Основное содержимое', 'content')}
    </S.DsPageLayout>
    </div>
    <p className={'cap'}>
    {'На узкой ширине боковые регионы раскрываются кнопками. На широком экране их ширина задана через leftWidth и rightWidth.'}
    </p>
    </div>
    </div>;
}

const exampleStyles = ".dspagelayout-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dspagelayout-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dspagelayout-example p{margin:0}\n.dspagelayout-example .row{display:flex;flex-wrap:wrap;gap:8px;align-items:center}\n.dspagelayout-example .cap{font:var(--ds-type-caption);color:var(--ds-fg-muted)}\n.dspagelayout-example .stage{border:1px solid var(--ds-border);min-width:0}\n.dspagelayout-example .region{padding:12px;background:var(--ds-surface);overflow-wrap:anywhere}\n.dspagelayout-example .region.side{flex:1}\n.dspagelayout-example .region.content{min-height:180px;flex:1}\n.dspagelayout-example .region.header,.dspagelayout-example .region.footer{background:var(--ds-bg)}\n.dspagelayout-example .region.header{border-bottom:1px solid var(--ds-border)}\n.dspagelayout-example .region.footer{border-top:1px solid var(--ds-border)}";

export { App as Example };

